class BillingClient:
    def __init__(self, base_url: str, token: str) -> None:
        self._http = httpx.Client(base_url=base_url, timeout=5.0,
                                  headers={"authorization": f"Bearer {token}"})
        self._cache: dict[str, Invoice] = {}

    def get_invoice(self, invoice_id: str) -> Invoice:
        if invoice_id not in self._cache:              # cached lookup
            r = self._http.get(f"/invoices/{invoice_id}")
            r.raise_for_status()                       # HttpStatusError
            self._cache[invoice_id] = Invoice.model_validate(r.json())
        return self._cache[invoice_id]
